BEGIN;
CREATE TABLE IF NOT EXISTS schema_migrations(version VARCHAR(64) PRIMARY KEY,applied_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS portfolios(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,starting_capital NUMERIC(24,10) NOT NULL,cash NUMERIC(24,10) NOT NULL,realised_pnl NUMERIC(24,10) NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS settings(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,risk_profile TEXT NOT NULL DEFAULT 'balanced',max_position_pct NUMERIC(12,6) NOT NULL DEFAULT 5,max_daily_loss_pct NUMERIC(12,6) NOT NULL DEFAULT 2,auto_scan INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS holdings(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,symbol TEXT NOT NULL,name TEXT NOT NULL,quantity INTEGER NOT NULL,average_price NUMERIC(24,10) NOT NULL,opened_at TIMESTAMPTZ NOT NULL,UNIQUE(user_id,symbol));
CREATE TABLE IF NOT EXISTS trades(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,symbol TEXT NOT NULL,name TEXT NOT NULL,action TEXT NOT NULL CHECK(action IN ('BUY','SELL')),quantity INTEGER NOT NULL,price NUMERIC(24,10) NOT NULL,realised_pnl NUMERIC(24,10) NOT NULL DEFAULT 0,confidence NUMERIC(12,6) NOT NULL,strategy TEXT NOT NULL,reasoning TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'FILLED',created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS agent_runs(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,status TEXT NOT NULL,stocks_scanned INTEGER NOT NULL,opportunities INTEGER NOT NULL,trades_placed INTEGER NOT NULL,summary TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS watchlist_snapshots(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,symbol TEXT NOT NULL,name TEXT NOT NULL,price NUMERIC(24,10) NOT NULL,change_pct NUMERIC(14,8) NOT NULL,confidence NUMERIC(12,6) NOT NULL,reasoning TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS stock_analyses(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,symbol TEXT NOT NULL,timeframe TEXT NOT NULL,bias TEXT NOT NULL,confidence NUMERIC(12,6) NOT NULL,payload TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_analysis_user_symbol ON stock_analyses(user_id,symbol,id DESC);
CREATE TABLE IF NOT EXISTS sentiment_snapshots(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,symbol TEXT NOT NULL,score NUMERIC(14,8) NOT NULL,label TEXT NOT NULL,confidence NUMERIC(12,6) NOT NULL,payload TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sentiment_user_symbol ON sentiment_snapshots(user_id,symbol,id DESC);
CREATE TABLE IF NOT EXISTS news_articles(id BIGSERIAL PRIMARY KEY,provider TEXT NOT NULL,external_id TEXT,content_hash TEXT UNIQUE NOT NULL,headline TEXT NOT NULL,summary TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT 'Unknown',url TEXT NOT NULL DEFAULT '',published_at TIMESTAMPTZ NOT NULL,received_at TIMESTAMPTZ NOT NULL,raw_payload TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS news_article_symbols(article_id BIGINT NOT NULL REFERENCES news_articles(id) ON DELETE CASCADE,exchange TEXT NOT NULL DEFAULT 'NSE',symbol TEXT NOT NULL,relevance NUMERIC(12,8) NOT NULL DEFAULT 1,PRIMARY KEY(article_id,exchange,symbol));
CREATE INDEX IF NOT EXISTS idx_news_symbol ON news_article_symbols(symbol,article_id DESC);
CREATE TABLE IF NOT EXISTS news_ingestion_logs(id BIGSERIAL PRIMARY KEY,provider TEXT NOT NULL,query TEXT NOT NULL,status TEXT NOT NULL,articles_received INTEGER NOT NULL DEFAULT 0,latency_ms INTEGER NOT NULL DEFAULT 0,error TEXT,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS ai_gateway_logs(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,request_hash TEXT NOT NULL,provider TEXT NOT NULL,model TEXT NOT NULL,status TEXT NOT NULL,latency_ms INTEGER NOT NULL,cached INTEGER NOT NULL DEFAULT 0,response_text TEXT,error TEXT,created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_gateway_user_created ON ai_gateway_logs(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS derivative_plans(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,symbol TEXT NOT NULL,strategy TEXT NOT NULL,market_view TEXT NOT NULL,spot NUMERIC(24,10) NOT NULL,expiry DATE NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PAPER_READY',created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS bot_conversations(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS bot_messages(id BIGSERIAL PRIMARY KEY,conversation_id BIGINT NOT NULL REFERENCES bot_conversations(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN ('user','assistant','system')),content TEXT NOT NULL,metadata TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS monitoring_events(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE CASCADE,component TEXT NOT NULL,level TEXT NOT NULL,message TEXT NOT NULL,payload TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS idx_monitoring_created ON monitoring_events(created_at DESC);
CREATE TABLE IF NOT EXISTS risk_policies(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,max_order_value NUMERIC(24,10) NOT NULL DEFAULT 50000,max_gross_exposure_pct NUMERIC(12,6) NOT NULL DEFAULT 50,max_sector_exposure_pct NUMERIC(12,6) NOT NULL DEFAULT 20,max_open_positions INTEGER NOT NULL DEFAULT 10,max_orders_per_day INTEGER NOT NULL DEFAULT 20,quote_max_age_seconds INTEGER NOT NULL DEFAULT 10,min_confidence NUMERIC(12,6) NOT NULL DEFAULT 72,allow_derivatives INTEGER NOT NULL DEFAULT 0,require_approval INTEGER NOT NULL DEFAULT 1,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS kill_switches(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,active INTEGER NOT NULL DEFAULT 0,reason TEXT NOT NULL DEFAULT '',activated_at TIMESTAMPTZ,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS order_intents(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,client_order_id TEXT UNIQUE NOT NULL,symbol TEXT NOT NULL,exchange TEXT NOT NULL,transaction_type TEXT NOT NULL CHECK(transaction_type IN ('BUY','SELL')),quantity INTEGER NOT NULL,order_type TEXT NOT NULL,limit_price NUMERIC(24,10),product TEXT NOT NULL,strategy TEXT NOT NULL,confidence NUMERIC(12,6) NOT NULL,reasoning TEXT NOT NULL,status TEXT NOT NULL,risk_payload TEXT NOT NULL DEFAULT '{}',broker_order_id TEXT,approved_at TIMESTAMPTZ,submitted_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS order_events(id BIGSERIAL PRIMARY KEY,order_intent_id BIGINT NOT NULL REFERENCES order_intents(id) ON DELETE CASCADE,event_type TEXT NOT NULL,payload TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS broker_connections(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,broker TEXT NOT NULL DEFAULT 'zerodha',status TEXT NOT NULL DEFAULT 'DISCONNECTED',broker_user_id TEXT,session_expires_at TIMESTAMPTZ,last_heartbeat_at TIMESTAMPTZ,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS broker_auth_states(state TEXT PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL,used INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS revoked_tokens(token_hash TEXT PRIMARY KEY,expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL);
INSERT INTO schema_migrations(version) VALUES('v3_1_application') ON CONFLICT DO NOTHING;
COMMIT;
